var e={land:8,water:12,air:8,stay:24},t=[{i:1,name:`On foot (laden)`,speed:3,domain:`land`,hoursPerDay:8},{i:2,name:`On foot (light)`,speed:5,domain:`land`,hoursPerDay:8},{i:3,name:`Horseback (no spare horse)`,speed:7,domain:`land`,hoursPerDay:8},{i:4,name:`Horseback (spare horse)`,speed:12,domain:`land`,hoursPerDay:10},{i:5,name:`Carriage`,speed:6,domain:`land`,hoursPerDay:10},{i:6,name:`Stagecoach`,speed:10,domain:`land`,hoursPerDay:12},{i:7,name:`Train`,speed:40,domain:`land`,hoursPerDay:24},{i:8,name:`Automobile`,speed:50,domain:`land`,hoursPerDay:10},{i:9,name:`Modern Automobile`,speed:80,domain:`land`,hoursPerDay:12},{i:10,name:`Rowboat`,speed:4,domain:`water`,hoursPerDay:8},{i:11,name:`Sailing boat`,speed:6,domain:`water`,hoursPerDay:12},{i:12,name:`Sailing Ship`,speed:10,domain:`water`,hoursPerDay:24},{i:13,name:`Steamship`,speed:25,domain:`water`,hoursPerDay:24},{i:14,name:`Modern Ship`,speed:35,domain:`water`,hoursPerDay:24},{i:15,name:`Aircraft`,speed:120,domain:`air`,hoursPerDay:4},{i:16,name:`Dirigible`,speed:20,domain:`air`,hoursPerDay:24},{i:17,name:`Helicopter`,speed:220,domain:`air`,hoursPerDay:6},{i:18,name:`Modern Airplane`,speed:800,domain:`air`,hoursPerDay:12},{i:19,name:`Teleport`,speed:1e4,domain:`air`,hoursPerDay:24},{i:20,name:`Stay`,speed:0,domain:`stay`,hoursPerDay:24}],n=new class{get all(){return options.map.transports}getDefaults(){return t.map(e=>({...e}))}get(e){return this.all.find(t=>t.name===e)}getDomain(e){return this.get(e)?.domain??`air`}getHoursPerDay(t){let n=this.get(t);return n?this.resolveHoursPerDay(n):e[this.getDomain(t)]}resolveHoursPerDay(t){let n=Number(t.hoursPerDay);return Number.isFinite(n)&&n>0&&n<=24?n:e[t.domain]??e.land}getByDomain(e){return this.all.find(t=>t.domain===e)}getNextId(){return this.all.length?Math.max(...this.all.map(e=>e.i))+1:0}set(e){options.map.transports=e,Options.save()}};window.Transports=n;export{n as t};